{"point":{"id":"changes","title":"Isolated Change Proposals","rationale":"ChangeSessionService captures repository commits, hunks, and canvas baselines into isolated proposals. Proposal edits use the shared controller and retain their own history and receipts. Acceptance checks both live and published baselines before publishing affected canvases. The two-step workflow and push integration provide automated entry paths into this review boundary.","sourcePaths":["application/mapping/changes/changeSessionService.ts","application/mapping/changes/diffSessionWorkflowService.ts","application/mapping/changes/diffSessionTools.ts","domain/mapping/changes/diagramChangeSession.ts","domain/mapping/changes/diffTree.ts","infrastructure/mapping/changes/changeSessionRecords.ts","application/core/integrations/pushIntegrationService.ts"],"relationships":[{"pointId":"canvas_commands","label":"applies proposal edits through isolated controller histories","kind":"call"},{"pointId":"persistence","label":"publishes accepted canvases with durable acceptance receipts","kind":"call"},{"pointId":"source_evidence","label":"pins repository context and captures Git hunks","kind":"dependency"},{"pointId":"agent_access","label":"exposes scoped tools to the materialization workflow","kind":"call"}]},"sources":[{"path":"application/mapping/changes/changeSessionService.ts","text":"import { importDiagramRevision } from '../../../domain/core/diagrams/diagramRevisionStore';
import { buildChangeTreemaps } from '../../../domain/mapping/changes/changeTreemap';
import { defaultDiffTree, diffTreeSummary, diffTreeNodes, resolveDiffTreeHunks, validateDiffTree, writeDiffTree, type DiffTreeInput } from '../../../domain/mapping/changes/diffTree';
import type { RepositoryContext } from '../../../domain/core/repositories/repository';
import type { GitDiffHunk } from '../../../domain/core/diffs/gitDiffHunk';
import { migrationIssues, type DiagramMigration } from '../../../domain/mapping/changes/diagramMigration';
import { canvasDisplayNodes } from '../../../domain/mapping/workspace/canvasDisplayNode';
import { DefaultCanvasHistoryService } from '../../../domain/core/diagrams/canvasHistoryService';
import { historyFromRevision, documentFromRevision } from '../../../domain/core/diagrams/projectDiagramCanvas';
import { diagramContentNodes } from '../../../domain/core/diagrams/diagramContentNodes';
import { createHash, randomUUID } from 'node:crypto';
import type { DiagramRepository } from '../../core/ports/diagramRepository';
import type { CanvasSessionPort } from '../agent/ports';
import type { LiveDocumentSnapshot, LiveDocumentState } from '../../../domain/mapping/agent/contracts';
import type { DiagramChangeSessionRepository } from './ports';
import { summarizeChangeSession, type ChangeDocumentState, type ChangeSessionDocument, type DiagramChangeSession, type DiagramChange } from '../../../domain/mapping/changes/diagramChangeSession';
import { MappingDocumentController, type DiagramOperation } from '../../../domain/mapping/workspace/mappingDocumentController';
